# FINISH GHANA BLUE ECONOMY RAW-SOURCE REPRODUCTION AUDIT
# Compares outputs already regenerated by the isolated raw-source pipeline.
# Does NOT re-extract source archives or modify original research outputs.

library(data.table)

project_dir <- file.path(Sys.getenv("OneDrive"), "Desktop", "blue economy")
main_output <- file.path(project_dir, "Blue_Economy_R_Results")
audit_root <- file.path(main_output, "Final_Reproducibility_Audit", "Raw_Source_Reproduction_FIXED")
filenames <- c("ghana_coastal_fishing_grid_monthly.csv",
               "ghana_coastal_gfw_nasa_spatial_panel.csv")
keys <- c("date", "lat", "lon")

stopifnot(dir.exists(audit_root), dir.exists(main_output))
original_paths <- file.path(main_output, filenames)
rebuilt_paths <- file.path(audit_root, filenames)

if (!all(file.exists(original_paths)) || !all(file.exists(rebuilt_paths))) {
  stop("MISSING FILES. Regenerated dataset(s) not found: ",
       paste(filenames[!file.exists(rebuilt_paths)], collapse = ", "),
       ". Do not claim raw-source reproduction.")
}
if (any(is.na(file.info(rebuilt_paths)$size)) ||
    any(file.info(rebuilt_paths)$size < 100)) {
  stop("A regenerated dataset is empty or unexpectedly small.")
}

compare_file <- function(filename) {
  old <- fread(file = file.path(main_output, filename))
  new <- fread(file = file.path(audit_root, filename))
  if (!nrow(old) || !nrow(new)) stop("Empty dataset: ", filename)
  if (!all(keys %in% names(old)) || !all(keys %in% names(new))) {
    stop("Missing date/lat/lon in ", filename)
  }
  if (anyNA(old[, ..keys]) || anyNA(new[, ..keys])) {
    stop("Missing key values in ", filename)
  }
  if (anyDuplicated(old, by = keys) || anyDuplicated(new, by = keys)) {
    stop("Duplicate date-lat-lon keys in ", filename)
  }
  missing_keys <- nrow(fsetdiff(old[, ..keys], new[, ..keys]))
  extra_keys <- nrow(fsetdiff(new[, ..keys], old[, ..keys]))
  missing_cols <- setdiff(names(old), names(new))
  added_cols <- setdiff(names(new), names(old))
  mismatches <- NA_integer_
  max_delta <- NA_real_
  if (missing_keys == 0L && extra_keys == 0L &&
      !length(missing_cols) && !length(added_cols) && nrow(old) == nrow(new)) {
    setkeyv(old, keys)
    setkeyv(new, keys)
    measures <- setdiff(names(old), keys)
    if (!length(measures)) stop("No measurement variables in ", filename)
    bad <- integer(length(measures))
    maxes <- numeric(length(measures))
    for (j in seq_along(measures)) {
      x <- old[[measures[j]]]
      y <- new[[measures[j]]]
      missing_diff <- xor(is.na(x), is.na(y))
      both <- !is.na(x) & !is.na(y)
      if (is.numeric(x) && is.numeric(y)) {
        delta <- abs(x[both] - y[both])
        bad[j] <- sum(missing_diff) + sum(!is.finite(delta) | delta > 1e-8)
        maxes[j] <- if (length(delta)) max(delta) else 0
      } else {
        bad[j] <- sum(missing_diff) + sum(as.character(x[both]) != as.character(y[both]))
        maxes[j] <- NA_real_
      }
    }
    mismatches <- sum(bad)
    max_delta <- if (all(is.na(maxes))) NA_real_ else max(maxes, na.rm = TRUE)
  }
  data.table(file = filename,
             original_rows = nrow(old), regenerated_rows = nrow(new),
             missing_keys = missing_keys, extra_keys = extra_keys,
             mismatched_values = mismatches,
             max_numeric_difference = max_delta,
             missing_columns = paste(missing_cols, collapse = "; "),
             added_columns = paste(added_cols, collapse = "; "))
}

report <- rbindlist(lapply(filenames, compare_file))
stopifnot(nrow(report) == 2L)
fwrite(report, file.path(audit_root, "raw_source_comparison_verified.csv"))
cat("\nRAW SOURCE REPRODUCTION COMPARISON\n")
print(report)

passed <- isTRUE(
  nrow(report) == 2L &&
    all(report$original_rows > 0L) &&
    all(report$original_rows == report$regenerated_rows) &&
    all(report$missing_keys == 0L) &&
    all(report$extra_keys == 0L) &&
    all(!is.na(report$mismatched_values)) &&
    all(report$mismatched_values == 0L) &&
    all(report$missing_columns == "") &&
    all(report$added_columns == "")
)

if (!passed) {
  stop("REVIEW REQUIRED: raw-source outputs differ or are incomplete. See raw_source_comparison_verified.csv")
}
writeLines(
  "PASS: Both intermediate datasets regenerated from raw archives and match originals (numeric tolerance 1e-8).",
  file.path(audit_root, "RAW_SOURCE_AUDIT_PASS_VERIFIED.txt")
)
cat("\nPASS: BOTH INTERMEDIATE DATASETS REPRODUCED.\n")